        val fingerprint = Fingerprint.compute(
            bank = parsed.bank,
            accountHint = parsed.accountHint,
            type = parsed.txType(),
            amountMinor = parsed.amountMinor,
            txAt = parsed.txAt,
            description = parsed.description,
        )
